'use strict';
const D=window.RESEARCH,A=D.atlas,G=D.guide,$=id=>document.getElementById(id);
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const arr=x=>Array.isArray(x)?x:x?[x]:[],plain=x=>typeof x==='string'?x:JSON.stringify(x??''),normal=x=>String(x).normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();
const ext=(u,t)=>/^https?:\/\//.test(u||'')?`<a href="${esc(u)}" target="_blank" rel="noopener noreferrer">${esc(t||u)}</a>`:esc(t||'Source unavailable');
const chapterBy=Object.fromEntries(D.chapters.map(x=>[x.id,x])),scholarBy=Object.fromEntries(A.labs.map(x=>[x.id,x])),paperBy=Object.fromEntries(D.papers.map(x=>[x.id,x])),personBy=Object.fromEntries(D.people.map(x=>[x.id,x]));
const url=(kind,id='')=>'#/'+kind+(id?'/'+encodeURIComponent(id):''),clink=(id,label)=>chapterBy[id]?`<a class="chip" href="${url('chapter',id)}">${esc(label||chapterBy[id].title)}</a>`:'',slink=id=>scholarBy[id]?`<a class="chip" href="${url('scholar',id)}">${esc(scholarBy[id].professor)}</a>`:'';
let state={saved:{},notes:{},reviewed:{}},filters={scholars:{q:'',region:'',university:'',chapter:'',evidence:''},papers:{q:'',chapter:'',kind:'landmark',sort:'year-desc'},universities:{q:'',region:''},glossary:{q:'',chapter:''}},pages={scholars:1,papers:1};
try{const saved=JSON.parse(localStorage.getItem('research-encyclopedia-v1')||'null');if(saved)state={saved:saved.saved||{},notes:saved.notes||{},reviewed:saved.reviewed||{}}}catch{}
let mapFocus='foundations',mapZoom=1,networkFocus='person-youngwoonlee',networkDepth=2,networkKind='',deskTab='all',currentRoute={type:'home',id:''},toastTimer;
function persist(){try{localStorage.setItem('research-encyclopedia-v1',JSON.stringify(state))}catch{toast('Browser storage is unavailable. Export your reading desk to keep it.')}}
function toast(text){$('toast').textContent=text;$('toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').classList.remove('visible'),2400)}
const saveKey=(kind,id)=>kind+':'+id;
function saveButton(kind,id,label='Save to reading desk'){const yes=!!state.saved[saveKey(kind,id)];return `<button class="save-button ${yes?'saved':''}" data-save-kind="${kind}" data-save-id="${esc(id)}" aria-pressed="${yes}">${yes?'Saved':esc(label)}</button>`}
function noteField(kind,id){const key=saveKey(kind,id);return `<div class="reading-note"><h3>Your reading notes</h3><p class="small">What is the claim, which assumption matters, and what would you test next?</p><textarea data-note="${esc(key)}" aria-label="Your reading notes" placeholder="Write a question, paper insight or project idea…">${esc(state.notes[key]||'')}</textarea><p class="small">Saved only in this browser. Back up your notes from My reading desk.</p></div>`}
function empty(title,copy){return `<div class="empty"><h3>${esc(title)}</h3><p>${esc(copy)}</p></div>`}
function head(title,copy,extra='',cls=''){return `<header class="page-head ${cls}"><h1>${title}</h1><div><p>${copy}</p>${extra}</div></header>`}
function bread(kind,label){return `<div class="bread"><a href="#/">Atlas</a><span>/</span><a href="${url(kind)}">${esc(label)}</a></div>`}
function sources(list){return `<ol class="source-list">${arr(list).map(s=>`<li>${typeof s==='string'?ext(s,s):ext(s.url,s.label||s.title||'Source')}${s.supports?`<br><span class="small">${esc(plain(s.supports))}</span>`:''}</li>`).join('')}</ol>`}
function tags(items){return arr(items).map(t=>`<span class="tag">${esc(t)}</span>`).join('')}
function fit(x){return `<div class="fit-line">${[['GNC',x.fit_gnc],['Autonomy',x.fit_autonomy],['Robot learning',x.fit_robot_learning]].map(([label,v])=>`<span>${v==='High'?'<strong>':''}${label}: ${esc(v)}${v==='High'?'</strong>':''}</span>`).join('')}</div>`}
function badge(x){return `<span class="tag ${x.recent_publications.length?'paper':''}">${esc(x.evidence_level)}</span>${x.historical?'<span class="tag warn">Historical / unavailable</span>':x.incoming?'<span class="tag warn">Incoming</span>':''}`}
function option(value,label,selected){return `<option value="${esc(value)}"${value===selected?' selected':''}>${esc(label)}</option>`}
function chapterOptions(selected){return option('','All fields',selected)+D.chapters.map(c=>option(c.id,c.title,selected)).join('')}
function paginate(type,count,size=24){const page=pages[type],n=Math.max(1,Math.ceil(count/size));return `<div class="pagination"><button data-page="${type}" data-change="-1" ${page<=1?'disabled':''}>Previous</button><span>Page ${page} of ${n} · ${count.toLocaleString()} records</span><button data-page="${type}" data-change="1" ${page>=n?'disabled':''}>Next</button></div>`}
function pathPreview(p){return `<article class="route-preview"><h3><a href="${url('path',p.id)}" style="color:inherit;text-decoration:none">${esc(p.title)}</a></h3><p>${esc(p.description)}</p><div class="route-sequence">${p.chapters.map(i=>esc(chapterBy[i]?.title||i)).join(' → ')}</div><a class="text-link" href="${url('path',p.id)}">Follow this reading path</a></article>`}
function overview(){return `<div class="wrap">${head('How robots understand,<br>decide and act.','Explore the ideas connecting control, autonomy and robot learning. Follow a question into its methods, papers, and research communities.',`<div class="actions"><a class="button" href="#/chapters">Explore the encyclopedia</a><a class="text-link" href="#/learn">Find a place to begin</a></div>`,'home-head')}<section aria-label="Interactive field map"><div id="mapMount">${fieldMap()}</div><div class="map-caption"><p>Select a field to reveal its connections. Lines describe conceptual relationships, not a ranking or a complete dependency graph.</p><a href="#/network">Explore scholar relationships</a></div><details class="map-accessible"><summary>Browse the map as a list</summary><div class="chips">${D.chapters.map(c=>clink(c.id)).join('')}</div></details></section><section class="section"><div class="section-heading"><h2>One feedback loop.<br>Many research questions.</h2><p>These communities study different parts of the same physical problem. A useful connection is often a shared assumption, representation or failure mode.</p></div><div class="loop">${D.overview.loop.map(s=>`<article class="loop-step"><h3>${esc(s.title)}</h3><p>${esc(s.text)}</p></article>`).join('')}</div><p class="small">A conceptual organization for learning; real systems interleave these operations. Further study: ${D.overview.sources.map(s=>ext(s.url,s.label)).join(' · ')}.</p></section></div><section class="wash section"><div class="wrap"><div class="section-heading"><h2>Choose a route through the field.</h2><a class="text-link" href="#/learn">All six reading paths</a></div><div class="route-grid">${D.paths.slice(0,3).map(pathPreview).join('')}</div></div></section><div class="wrap section"><div class="coverage-strip"><div><h3>A research map you can inspect.</h3><p>Every profile keeps its sources and gaps. The encyclopedia adds interpretation; the directory records the underlying research evidence.</p><a class="text-link" href="#/about">See scope and coverage</a></div><div><strong>${D.stats.chapters}</strong><span>connected field chapters</span></div><div><strong>${D.stats.landmarks}</strong><span>selected landmark readings</span></div><div><strong>${A.stats.labs}</strong><span>professor / group records</span></div></div></div>`}
function fieldMap(){const c=chapterBy[mapFocus]||D.chapters[0];if(!c)return empty('Preparing the field map','The content bundle has not loaded.');mapFocus=c.id;const connected=D.concept_edges.filter(e=>e.from===c.id||e.to===c.id),near=new Set([c.id,...connected.flatMap(e=>[e.from,e.to])]),pos={};D.families.forEach((f,col)=>f.ids.forEach((id,row)=>pos[id]={x:155+col*310,y:82+row*76}));const paths=D.concept_edges.map((e,i)=>{const s=pos[e.from],t=pos[e.to];if(!s||!t)return '';const active=e.from===c.id||e.to===c.id;let d=s.x===t.x?`M${s.x+104},${s.y} C${s.x+145},${s.y} ${t.x+145},${t.y} ${t.x+104},${t.y}`:`M${s.x+(s.x<t.x?104:-104)},${s.y} C${(s.x+t.x)/2},${s.y} ${(s.x+t.x)/2},${t.y} ${t.x+(s.x<t.x?-104:104)},${t.y}`;return `<path class="map-edge ${active?'active':'inactive'}" d="${d}"><title>${esc(e.label+': '+e.explanation)}</title></path>`}).join('');return `<div class="map-layout"><div class="map-canvas"><div class="map-tools"><p>Choose a question. Follow its connections.</p><div class="map-controls"><button data-zoom="-1" aria-label="Zoom out field map">−</button><button data-zoom="1" aria-label="Zoom in field map">+</button><button data-zoom="0" aria-label="Reset field map zoom">Reset</button></div></div><div class="diagram-scroll"><svg class="field-svg" style="width:${mapZoom*100}%;max-height:${610*mapZoom}px" viewBox="0 0 930 530" role="group" aria-label="Field relationships, with selected field ${esc(c.title)}">${D.families.map((f,i)=>`<text class="map-band" x="${155+i*310}" y="26" text-anchor="middle">${esc(f.name)}</text>`).join('')}${paths}${D.chapters.map(n=>{const p=pos[n.id];const title=n.short_title||n.title;const words=title.split(' ');let lines=[title];if(title.length>24){let k=Math.ceil(words.length/2);lines=[words.slice(0,k).join(' '),words.slice(k).join(' ')]}return `<g class="map-node ${n.id===c.id?'selected':near.has(n.id)?'neighbor':'faded'}" transform="translate(${p.x},${p.y})" data-map="${n.id}" role="button" tabindex="0" aria-label="Explore ${esc(title)}" aria-pressed="${n.id===c.id}"><rect x="-104" y="-27" width="208" height="54" rx="4"/>${lines.map((line,i)=>`<text text-anchor="middle" y="${lines.length===1?5:-3+i*18}">${esc(line)}</text>`).join('')}</g>`}).join('')}</svg></div></div><aside class="map-aside" aria-live="polite"><h2>${esc(c.title)}</h2><p class="question">${esc(c.question)}</p><p class="summary">${esc(c.summary.slice(0,165))}${c.summary.length>165?'…':''}</p><div class="actions"><a class="button" href="${url('chapter',c.id)}">Read this field</a></div><h3>What connects here</h3><ul>${connected.slice(0,3).map(e=>`<li><strong>${esc(e.label)}</strong><br>${esc(e.explanation.slice(0,145))}${e.explanation.length>145?'…':''}</li>`).join('')||'<li>Browse related fields in the chapter.</li>'}</ul><p class="small">Editorial concept links. Primary reading sources appear inside each chapter.</p></aside></div>`}
function chaptersPage(){return `<div class="wrap">${head('A field guide,<br>with the connections intact.','Read each field as a research question: what is being modeled, what evidence counts, and which assumptions become fragile.')}<div class="actions" style="margin:0 0 30px"><a class="button secondary" href="#/glossary">Open the glossary</a><a class="text-link" href="#/learn">Browse structured reading paths</a></div>${D.families.map(f=>`<section class="section" style="padding-top:15px"><div class="family-title"><span class="family-dot ${f.id}"></span><h2>${esc(f.name)}</h2></div><div class="chapter-grid">${f.ids.map(id=>chapterBy[id]).filter(Boolean).map(c=>`<article class="chapter-entry"><h3><a href="${url('chapter',c.id)}">${esc(c.title)}</a></h3><p>${esc(c.question)}</p><p class="small">${c.reading_minutes} min overview · ${c.paper_ids.length} selected readings</p><div class="actions"><a class="text-link" href="${url('chapter',c.id)}">Read chapter</a></div></article>`).join('')}</div></section>`).join('')}</div>`}
function paperRow(q,compact=false){const scholars=q.scholar_ids.map(id=>scholarBy[id]?.professor).filter(Boolean);return `<article class="paper-row ${compact?'compact':''}"><div class="paper-year">${esc(q.year)}</div><div><h3><a href="${url('paper',q.id)}">${esc(q.title)}</a></h3><p class="authors">${esc(q.authors|| (scholars.length?'Associated profiles: '+scholars.join(', '):'See primary source for author list'))}</p><p class="small">${esc(q.venue)}</p><div class="actions">${saveButton('paper',q.id,'Save paper')}<a class="text-link" href="${url('paper',q.id)}">Reading note</a>${ext(q.url,'Primary source')}</div></div><div class="contribution"><span class="tag">${esc(q.role)}</span><p>${esc(q.contribution)}</p></div></article>`}
function chapterPage(id){const c=chapterBy[id];if(!c)return notFound();const refs=c.paper_ids.map(i=>paperBy[i]).filter(Boolean);const family=D.families.find(f=>f.id===c.family);return `<div class="wrap">${bread('chapters','Encyclopedia')}${head(esc(c.title),esc(c.subtitle||c.question),`<p class="small">${esc(family.name)} · ${c.reading_minutes} min overview</p><div class="actions">${saveButton('chapter',c.id,'Save chapter')}</div>`)}<div class="article-layout"><aside class="contents"><p>In this chapter</p>${c.sections.map((s,i)=>`<a href="#section-${i}" data-scroll="section-${i}">${esc(s.heading)}</a>`).join('')}<a href="#questions" data-scroll="questions">Open questions</a><a href="#readings" data-scroll="readings">Selected readings</a><a href="#scholars" data-scroll="scholars">Scholars & labs</a><a href="#project" data-scroll="project">A concrete project</a><a href="#sources" data-scroll="sources">Sources</a></aside><article class="article"><p class="summary">${esc(c.summary)}</p><div class="question-band">${esc(c.question)}</div><p class="small"><strong>Useful foundations:</strong> ${c.prerequisites.map(v=>chapterBy[v]?`<a href="${url('chapter',v)}">${esc(chapterBy[v].title)}</a>`:esc(v)).join(' · ')}</p>${c.sections.map((s,i)=>`<section id="section-${i}"><h2>${esc(s.heading)}</h2><p>${esc(s.text)}</p>${s.bullets?.length?`<ul>${s.bullets.map(t=>`<li>${esc(t)}</li>`).join('')}</ul>`:''}${s.sources?sources(s.sources):''}</section>`).join('')}<section id="questions"><h2>Questions still worth asking</h2><ul>${c.open_questions.map(q=>`<li>${esc(q)}</li>`).join('')}</ul><h3>Common reading traps</h3><ul>${c.pitfalls.map(q=>`<li>${esc(q)}</li>`).join('')}</ul></section><section id="readings"><h2>Selected readings</h2><p class="small">A deliberate starting shelf, not a complete bibliography or citation ranking. Open each note for its contribution and limits.</p>${refs.map(q=>paperRow(q,true)).join('')}</section><section id="scholars"><h2>People and research groups</h2><p class="small">An editorial set of relevant starting points. Inclusion does not imply a collaboration between these people or an available graduate place.</p><div class="chips">${c.scholar_ids.map(slink).join('')}</div>${c.context_scholars.length?`<p class="small" style="margin-top:18px">Additional names in the field context: ${c.context_scholars.map(esc).join(', ')}. These references do not add universities to the application shortlist.</p>`:''}<div class="actions"><a class="text-link" href="${url('scholars')}?chapter=${c.id}">Explore all topic-matched directory records</a></div></section><section id="project" class="project"><h3>${esc(c.project?.title||'A concrete preparation project')}</h3><p>${esc(c.project?.description||'')}</p><ul>${arr(c.project?.evaluation).map(v=>`<li>${esc(v)}</li>`).join('')}</ul></section><h2>Continue across the field</h2><div class="chips">${c.related.map(i=>clink(i)).join('')}</div><section id="sources"><h2>Sources and further study</h2>${sources(c.sources)}</section>${noteField('chapter',id)}</article></div></div>`}
function paperPage(id){const q=paperBy[id];if(!q)return notFound();return `<div class="wrap">${bread('papers','Paper library')}${head(esc(q.title),`${esc(q.authors||'Author list: consult primary source')}<br><span class="small">${esc(q.year)} · ${esc(q.venue)}</span>`,`<div class="actions"><a class="button" href="${esc(q.url)}" target="_blank" rel="noopener noreferrer">Read primary source</a>${saveButton('paper',id,'Save paper')}</div>`)}<div class="article-layout"><aside class="contents"><p>Reading note</p><a href="#contribution" data-scroll="contribution">Contribution</a><a href="#limits" data-scroll="limits">Limits</a><a href="#reading-questions" data-scroll="reading-questions">Reading questions</a><a href="#paper-connections" data-scroll="paper-connections">Connections</a></aside><article class="article"><span class="tag">${esc(q.role)}</span><section id="contribution"><h2>What this work contributes</h2><p>${esc(q.contribution)}</p>${q.why_read?`<h3>Why read it</h3><p>${esc(q.why_read)}</p>`:''}</section><section id="limits"><h2>What to keep in view</h2><p>${esc(q.limitations)}</p><div class="evidence-box"><p><strong>Review depth:</strong> ${esc(q.evidence_depth)}</p></div></section><section id="reading-questions"><h2>Questions for your reading</h2><ul>${(q.reading_questions.length?q.reading_questions:['What exact claim does the paper make, and what evidence supports it?','Which assumptions would fail in the setting you care about?','What is the strongest relevant baseline, and is the comparison fair?']).map(x=>`<li>${esc(x)}</li>`).join('')}</ul></section><section id="paper-connections"><h2>Connected fields</h2><div class="chips">${q.chapter_ids.map(i=>clink(i)).join('')}</div>${q.scholar_ids.length?`<h3>Associated directory profiles</h3><p class="small">These links preserve the selected-paper associations in the directory. They do not assert an equal contribution or an advising relationship.</p><div class="chips">${q.scholar_ids.map(slink).join('')}</div>`:''}</section>${q.version_ids?.length?`<h2>Related publication versions</h2><p class="small">A journal extension can change the experiments, claims and author list. These are linked reading records, not automatically independent research contributions.</p><div class="chips">${q.version_ids.map(id=>paperBy[id]).filter(Boolean).map(v=>`<a class="chip" href="${url('paper',v.id)}">${esc(v.year)} · ${esc(v.venue)}</a>`).join('')}</div>`:''}<h2>Source</h2><p>${ext(q.url,q.title)}</p>${q.sources?sources(q.sources):''}${noteField('paper',id)}</article></div></div>`}
function notFound(){return `<div class="wrap section">${empty('This page is not in the atlas','Use search or the field map to locate a chapter, scholar or paper.')}<a class="button" href="#/">Return to field map</a></div>`}
const scholarSearch=new Map(A.labs.map(x=>[x.id,normal([x.professor,x.university,x.department,x.lab,...x.topics,x.lineage,x.connections].map(plain).join(' '))]));
const paperSearch=new Map(D.papers.map(q=>[q.id,normal([q.title,q.authors,q.venue,q.contribution,...q.scholar_ids.map(id=>scholarBy[id]?.professor||'')].join(' '))]));
function filteredScholars(){const f=filters.scholars,q=normal(f.q.trim());return A.labs.filter(x=>(!q||scholarSearch.get(x.id).includes(q))&&(!f.region||x.region===f.region)&&(!f.university||x.university===f.university)&&(!f.chapter||x.chapter_ids.includes(f.chapter))&&(!f.evidence||x.evidence_level===f.evidence))}
function scholarRow(x){return `<article class="result-row"><div><h3><a href="${url('scholar',x.id)}">${esc(x.professor)}</a></h3><p>${esc(x.university)}<br>${esc(x.department)}</p>${saveButton('scholar',x.id,'Shortlist')}</div><div><p style="color:var(--ink);font-weight:550">${esc(x.lab)}</p><p>${esc(x.topics.join(' · '))}</p>${fit(x)}</div><div class="record-evidence">${badge(x)}<p>${x.recent_publications.length} selected paper records<br>${x.citations.count==null?'Citation count not verified':`${Number(x.citations.count).toLocaleString()} citations · ${esc(x.citations.provider)}`}</p><a href="${url('scholar',x.id)}" class="text-link">Open full profile</a></div></article>`}
function scholarResults(){const ls=filteredScholars();pages.scholars=Math.min(pages.scholars,Math.max(1,Math.ceil(ls.length/24)));return `<div class="result-line"><span>${ls.length.toLocaleString()} professor / group records</span><span>Topic fit is an editorial judgment</span></div><div class="result-list">${ls.slice((pages.scholars-1)*24,pages.scholars*24).map(scholarRow).join('')||empty('No matching profiles','Try a broader term or clear the filters.')}</div>${paginate('scholars',ls.length)}`}
function scholarsPage(){const f=filters.scholars;return `<div class="wrap">${head('Scholars & research groups.','Explore the recorded groups, then inspect their papers, training, current role and open checks. This is a research directory, not an admissions ranking.')}<div class="filters" data-filter-group="scholars"><label class="search-field">Search people, labs and topics<input type="search" data-filter="q" value="${esc(f.q)}" placeholder="Youngwoon Lee, navigation, manipulation…"></label><label>Region<select data-filter="region">${['','Korea','US','Europe'].map(v=>option(v,v||'All regions',f.region)).join('')}</select></label><label>University<select data-filter="university">${option('','All universities',f.university)}${A.universities.map(u=>u.university).sort().map(v=>option(v,v,f.university)).join('')}</select></label><label>Field<select data-filter="chapter">${chapterOptions(f.chapter)}</select></label><label>Evidence<select data-filter="evidence">${['','Publication attached','Profile verified','Directory lead'].map(v=>option(v,v||'All evidence levels',f.evidence)).join('')}</select></label><button data-clear="scholars">Clear filters</button></div><div id="scholarResults">${scholarResults()}</div></div>`}
function scholarPage(id){const x=scholarBy[id];if(!x)return notFound();const c=x.citations,person=D.people.find(p=>p.scholar_id===id),ps=x.paper_ids.map(i=>paperBy[i]).filter(Boolean);return `<div class="wrap">${bread('scholars','Scholars & labs')}${head(esc(x.professor),`${esc(x.university)}<br><span class="small">${esc(x.department)}</span>`,`<div class="actions">${ext(x.lab_url,'Official lab / faculty page')}</div>`)}<div class="profile-layout"><article class="profile-main"><h2>${esc(x.lab)}</h2><div class="chips">${tags(x.topics)}</div>${fit(x)}<div class="evidence-box">${badge(x)}<p style="margin-top:12px">${esc(x.appointment_status)}</p>${x.verification_note?`<p>${esc(x.verification_note)}</p>`:''}</div><h2>Research fit and evidence</h2><p>${esc(x.fit_reason)}</p><p>${esc(x.quality_evidence)}</p><h2>Selected publications</h2>${ps.length?ps.map(q=>paperRow(q,true)).join(''):empty('No specific paper attached yet','This record has a publication-evidence gap. It is not evidence that the group is inactive.')}<h2>Training lineage</h2><p>${esc(plain(x.lineage))}</p>${person?`<div class="actions"><a class="text-link" href="${url('network',person.id)}">Explore documented relationships</a></div>`:''}<h2>Professional connections</h2><p>${esc(plain(x.connections))}</p><p class="small">A documented relationship does not establish personal access, student exchanges or a recruiting opportunity.</p><h2>Connected fields</h2><p class="small">Topic links are navigational associations based on the recorded research areas.</p><div class="chips">${x.chapter_ids.map(i=>clink(i)).join('')}</div><h2>Unresolved checks</h2>${x.gaps.length?`<ul>${x.gaps.map(v=>`<li>${esc(v)}</li>`).join('')}</ul>`:'<p>No additional record-level gap is listed. Confirm current supervision and admission arrangements separately.</p>'}<h2>Sources</h2>${sources(x.sources)}</article><aside class="profile-aside"><h2>Application context</h2><p>${esc(plain(x.recruiting))}</p><h3>Citation snapshot</h3>${c.count!=null?`<p class="metric">${esc(c.count_relation||'')}${Number(c.count).toLocaleString()}</p><p>${esc(c.provider)}${c.h_index!=null?' · h-index '+esc(c.h_index):''}<br>${esc(c.snapshot_date||c.checked)}</p>`:'<p>Not verified</p>'}<p style="margin-top:13px">${esc(c.status)}</p>${c.source_url?`<p>${ext(c.source_url,'Metric source')}</p>`:''}<p class="small">Different providers count differently. This is not a quality or admissions score.</p>${x.citation_identity_review?`<details style="margin-top:14px"><summary>Identity check</summary><p>${esc(plain(x.citation_identity_review))}</p></details>`:''}<h3>Your shortlist</h3>${saveButton('scholar',id,'Add to shortlist')}<label class="check-label"><input type="checkbox" data-reviewed="${esc(id)}" ${state.reviewed[id]?'checked':''}>I reviewed this profile</label><label for="scholarNotes">Your notes</label><textarea id="scholarNotes" data-note="scholar:${id}" placeholder="Questions about papers, supervision or research fit…">${esc(state.notes['scholar:'+id]||'')}</textarea><p class="small">Stored only in this browser. Export from My reading desk to preserve your notes.</p></aside></div></div>`}
function filteredPapers(){const f=filters.papers,q=normal(f.q.trim());const ps=D.papers.filter(p=>(!q||paperSearch.get(p.id).includes(q))&&(!f.chapter||p.chapter_ids.includes(f.chapter))&&(!f.kind||p.kind===f.kind));ps.sort((a,b)=>f.sort==='year-asc'?(Number(a.year)||0)-(Number(b.year)||0):f.sort==='title'?a.title.localeCompare(b.title):(Number(b.year)||0)-(Number(a.year)||0));return ps}
function paperResults(){const ps=filteredPapers();pages.papers=Math.min(pages.papers,Math.max(1,Math.ceil(ps.length/24)));return `<div class="result-line"><span>${ps.length} distinct paper / reading records</span><span>Selected readings, not an exhaustive bibliography</span></div><div class="result-list">${ps.slice((pages.papers-1)*24,pages.papers*24).map(q=>paperRow(q)).join('')||empty('No matching papers','Try all fields, recent lab work, or a shorter search term.')}</div>${paginate('papers',ps.length)}`}
function papersPage(){const f=filters.papers;return `<div class="wrap">${head('The papers behind<br>the ideas.','Start with foundational and bridging work, then follow recent lab publications. Each reading note explains why the work matters and where its claims stop.')}<div class="filters" data-filter-group="papers"><label class="search-field">Search titles, authors and methods<input type="search" data-filter="q" value="${esc(f.q)}" placeholder="Kalman, diffusion policy, safety…"></label><label>Field<select data-filter="chapter">${chapterOptions(f.chapter)}</select></label><label>Shelf<select data-filter="kind">${option('landmark','Selected landmark readings',f.kind)}${option('recent','Recent lab work',f.kind)}${option('','All readings',f.kind)}</select></label><label>Order<select data-filter="sort">${[['year-desc','Newest first'],['year-asc','Oldest first'],['title','Title']].map(([v,t])=>option(v,t,f.sort)).join('')}</select></label><button data-clear="papers">Clear filters</button></div><div id="paperResults">${paperResults()}</div></div>`}
function universityResults(){const f=filters.universities;const us=A.universities.filter(u=>(!f.q||normal(u.university+' '+u.country+' '+u.departments_checked.join(' ')).includes(normal(f.q)))&&(!f.region||u.region===f.region));return `<div class="result-line"><span>${us.length} eligible universities</span></div><div class="table-scroll"><table><thead><tr><th>University</th><th>QS 2027</th><th>Recorded groups</th><th>Directories checked</th><th>Coverage</th></tr></thead><tbody>${us.map(u=>`<tr><td style="min-width:200px"><a href="${url('scholars')}?university=${encodeURIComponent(u.university)}">${esc(u.university)}</a><p>${esc(u.country)}</p></td><td>${ext(u.qs_source,'#'+u.qs_rank)}</td><td><strong>${u.lab_count}</strong><p>${u.publication_profiles} with papers</p></td><td style="min-width:250px;max-width:370px"><p>${u.departments_checked.map(esc).join('<br>')}</p><details><summary>Directory sources</summary>${sources(u.directory_sources)}</details></td><td style="min-width:260px;max-width:350px"><span class="tag warn">${esc(u.coverage_status)}</span><p>${esc(u.coverage_notes)}</p><details><summary>${u.outstanding.length} outstanding checks</summary><ul>${u.outstanding.map(v=>`<li>${esc(v)}</li>`).join('')}</ul></details></td></tr>`).join('')}</tbody></table></div>`}
function universitiesPage(){const f=filters.universities;return `<div class="wrap">${head('The application universe.','KAIST, SNU, POSTECH and Yonsei, plus US and European universities meeting your QS overall cutoff. No restriction on when a professor was appointed.')}<p class="notice">Foreign cutoff: QS World University Rankings 2027 overall ≤106, POSTECH’s rank. This rule limits application targets; it does not limit the historical or conceptual sources in the encyclopedia. ${ext('https://www.topuniversities.com/universities/pohang-university-science-technology-postech','QS ranking source')}</p><div class="filters" data-filter-group="universities"><label class="search-field">Search universities or departments<input type="search" data-filter="q" value="${esc(f.q)}" placeholder="A university, country or department…"></label><label>Region<select data-filter="region">${['','Korea','US','Europe'].map(v=>option(v,v||'All regions',f.region)).join('')}</select></label><button data-clear="universities">Clear filters</button></div><div id="universityResults">${universityResults()}</div></div>`}
function glossaryResults(){const f=filters.glossary,ts=D.glossary.filter(t=>(!f.q||normal(t.term+' '+t.definition).includes(normal(f.q)))&&(!f.chapter||t.chapter_ids.includes(f.chapter)));return `<div class="result-line"><span>${ts.length} concepts</span></div><div class="definition-grid">${ts.map(t=>`<article class="definition"><h3>${esc(t.term)}</h3><p>${esc(t.definition)}</p><div class="chips">${t.chapter_ids.map(i=>clink(i)).join('')}</div></article>`).join('')||empty('No matching term','Try a broader term or choose all fields.')}</div>`}
function glossaryPage(){const f=filters.glossary;return `<div class="wrap">${head('A shared vocabulary.','Short definitions for crossing disciplinary boundaries. Follow a term into its field chapter to recover the assumptions and context.')}<div class="filters" data-filter-group="glossary"><label class="search-field">Search terms and definitions<input type="search" data-filter="q" value="${esc(f.q)}" placeholder="Observability, embodiment, distribution shift…"></label><label>Field<select data-filter="chapter">${chapterOptions(f.chapter)}</select></label><button data-clear="glossary">Clear filters</button></div><div id="glossaryResults">${glossaryResults()}</div><div class="section"></div></div>`}
function learnPage(){return `<div class="wrap">${head('Build a mental model,<br>then choose a question.','Six routes through the encyclopedia. Each stage has a learning outcome and points to the papers, people and methods that make it concrete.')}<div class="route-grid section" style="padding-top:10px">${D.paths.map(pathPreview).join('')}</div><section class="section"><div class="section-heading"><h2>Methods solve different problems.</h2><p>A learned policy, an optimizer and a safety certificate can be parts of the same system. Compare the information each needs and the claim each supports.</p></div><div class="table-scroll"><table class="method-table"><thead><tr><th>Method family</th><th>What it needs</th><th>What it does</th><th>What to examine</th></tr></thead><tbody>${D.overview.methods.map(m=>`<tr><td><a href="${url('chapter',m[4])}">${esc(m[0])}</a></td><td>${esc(m[1])}</td><td>${esc(m[2])}</td><td>${esc(m[3])}</td></tr>`).join('')}</tbody></table></div><p class="small">Editorial comparison; use the linked chapters and primary readings for detailed assumptions and guarantees.</p></section></div>`}
function pathPage(id){const p=D.paths.find(p=>p.id===id);if(!p)return notFound();return `<div class="wrap">${bread('learn','Reading paths')}${head(esc(p.title),esc(p.description),`<p class="small">Six stages · work at your own pace</p><div class="actions">${saveButton('path',id,'Save path')}</div>`)}<div class="article-layout"><aside class="contents"><p>Your route</p>${p.chapters.map((i,n)=>`<a href="#step-${n}" data-scroll="step-${n}">${n+1}. ${esc(chapterBy[i]?.title||i)}</a>`).join('')}</aside><article class="article">${p.chapters.map((id,n)=>{const c=chapterBy[id];if(!c)return '';return `<section class="path-step" id="step-${n}"><div class="step-number">${n+1}</div><div><h3><a href="${url('chapter',id)}">${esc(c.title)}</a></h3><p>${esc(c.question)}</p><p class="outcome"><strong>After this stage:</strong> ${esc(p.outcomes[n])}</p><div class="chips">${c.paper_ids.slice(0,2).map(pid=>paperBy[pid]?`<a class="chip" href="${url('paper',pid)}">${esc(paperBy[pid].title)}</a>`:'').join('')}</div></div></section>`}).join('')}<div class="project"><h3>Turn reading into a research direction</h3><p>Choose one failure mode from the route. Write down the current approach, its assumption, a measurable failure case, and a minimal experiment that could distinguish your idea from the strongest baseline.</p><p>Then inspect the associated labs’ recent student-led papers. A coherent research question is a better starting point for an application than a long list of fashionable methods.</p></div>${noteField('path',id)}</article></div></div>`}
function relationshipClass(e){return /lab/i.test(e.kind)?'lab':/postdoc/i.test(e.kind)?'postdoc':'phd'}
function neighborhood(){const es=D.person_edges.filter(e=>!networkKind||relationshipClass(e)===networkKind),levels=new Map([[networkFocus,0]]);let frontier=[networkFocus];for(let step=0;step<networkDepth;step++){let next=[];for(const id of frontier)for(const e of es){let target=null,level=0;if(e.from_id===id){target=e.to_id;level=levels.get(id)+1}else if(e.to_id===id){target=e.from_id;level=levels.get(id)-1}if(target&&!levels.has(target)){levels.set(target,level);next.push(target)}}frontier=next}return {levels,edges:es.filter(e=>levels.has(e.from_id)&&levels.has(e.to_id))}}
function networkDiagram(){const n=personBy[networkFocus]||D.people[0];networkFocus=n.id;const {levels,edges}=neighborhood();const groups={};for(const[id,l]of levels)(groups[l]??=[]).push(id);const width=1120,max=Math.max(1,...Object.values(groups).map(x=>x.length)),height=Math.max(440,max*90+80),positions={};for(const [l,ids]of Object.entries(groups)){ids.sort((a,b)=>a===n.id?-1:b===n.id?1:personBy[a].name.localeCompare(personBy[b].name));ids.forEach((id,i)=>positions[id]={x:560+Number(l)*215,y:height/2+(i-(ids.length-1)/2)*88})}const direct=edges.filter(e=>e.from_id===n.id||e.to_id===n.id),xs=Object.values(positions).map(v=>v.x),viewX=Math.min(...xs)-110,viewW=Math.max(...xs)-Math.min(...xs)+220;return `<div class="network-layout"><div class="network-diagram"><svg viewBox="${viewX} 0 ${viewW} ${height}" role="group" aria-label="Documented training relationships near ${esc(n.name)}"><defs><marker id="mentor-arrow" viewBox="0 0 8 8" refX="7" refY="4" markerWidth="5" markerHeight="5" orient="auto"><path d="M0 0 8 4 0 8Z" fill="#416e91"/></marker></defs><text x="${viewX+20}" y="28" class="map-band">Mentor / lab PI → researcher</text>${edges.map((e,i)=>{const s=positions[e.from_id],t=positions[e.to_id],off=i%2?3:-3;return `<path class="mentor-edge ${relationshipClass(e)}" d="M${s.x+83},${s.y+off} C${(s.x+t.x)/2},${s.y+off} ${(s.x+t.x)/2},${t.y+off} ${t.x-85},${t.y+off}" marker-end="url(#mentor-arrow)"><title>${esc(personBy[e.from_id].name+' → '+personBy[e.to_id].name+': '+e.kind)}</title></path>`}).join('')}${[...levels.keys()].map(id=>{const p=positions[id],person=personBy[id],parts=person.name.split(' '),lines=person.name.length>23?[parts.slice(0,-1).join(' '),parts.at(-1)]:[person.name];return `<g class="person-node ${id===n.id?'selected':''}" transform="translate(${p.x},${p.y})" tabindex="0" role="button" data-person="${id}" aria-label="Focus on ${esc(person.name)}"><rect x="-84" y="-31" width="168" height="62" rx="4"/>${lines.map((l,i)=>`<text x="0" y="${lines.length===1?-2:-10+i*16}" text-anchor="middle">${esc(l)}</text>`).join('')}<text class="node-role" x="0" y="21" text-anchor="middle">${person.scholar_id?'Directory profile':'Referenced scholar'}</text></g>`}).join('')}</svg></div><aside class="network-details" aria-live="polite"><div><h2>${esc(n.name)}</h2><p>${esc(n.university)}</p>${n.scholar_id?`<div class="actions"><a class="button" href="${url('scholar',n.scholar_id)}">Open research profile</a></div>`:''}</div><div class="legend"><span><i></i>Doctoral relationship</span><span><i class="postdoc"></i>Postdoctoral mentor</span><span><i class="lab"></i>Named lab connection</span></div><ul class="connection-list">${direct.map(e=>`<li><strong>${esc(e.kind)}</strong><div>${esc(personBy[e.from_id].name)} → ${esc(personBy[e.to_id].name)}</div><p>${esc(e.note)}</p>${ext(e.url,'Evidence for this relationship')}</li>`).join('')||'<li>No captured edges match this filter. Try all relationship types.</li>'}</ul></aside></div><details class="map-accessible"><summary>All ${edges.length} relationships shown in this view</summary><ul class="connection-list">${edges.map(e=>`<li>${esc(personBy[e.from_id].name)} → ${esc(personBy[e.to_id].name)} · ${esc(e.kind)}<br>${ext(e.url,'Primary evidence')}</li>`).join('')}</ul></details>`}
function networkPage(){return `<div class="wrap">${head('People, ideas,<br>and documented paths.','Explore a sourced subset of training relationships. An advising link, postdoctoral appointment and research-topic overlap are different kinds of connection.')}<div class="filters"><label class="search-field">Focus scholar<select id="networkPerson">${[...D.people].sort((a,b)=>a.name.localeCompare(b.name)).map(p=>option(p.id,p.name,networkFocus)).join('')}</select></label><label>Neighborhood<select id="networkDepth">${option('1','Direct connections',String(networkDepth))}${option('2','Two steps',String(networkDepth))}</select></label><label>Relationship<select id="networkKind">${option('','All relationships',networkKind)}${option('phd','Doctoral relationships',networkKind)}${option('postdoc','Postdoctoral mentors',networkKind)}${option('lab','Named lab connections',networkKind)}</select></label></div><p class="small">${D.stats.person_edges} captured relationships among ${D.stats.people} referenced people. This is not a complete academic genealogy. Context scholars are not automatically eligible application targets. A relationship does not promise introductions or access.</p><div id="networkMount">${networkDiagram()}</div><section class="section"><div class="section-heading"><h2>Beyond a university department.</h2><p>Research institutes, joint laboratories and industry roles shape research communities. Degree enrollment and supervision arrangements still need a named university route.</p></div><div class="table-scroll"><table><thead><tr><th>Organization</th><th>Documented connection</th><th>Degree / application route</th></tr></thead><tbody>${A.network_institutions.map(n=>`<tr><td style="min-width:190px"><strong>${esc(n.institution)}</strong><p>${esc(n.type)}</p></td><td style="min-width:270px">${esc(n.connections)}<div class="small" style="margin-top:12px">${n.sources.map(s=>ext(s.url,s.label)).join(' · ')}</div></td><td style="min-width:240px">${esc(n.degree_route)}</td></tr>`).join('')}</tbody></table></div></section></div>`}
function aboutPage(){const evidence=['Publication attached','Profile verified','Directory lead'].map(t=>({title:t,n:A.labs.filter(x=>x.evidence_level===t).length}));return `<div class="wrap">${head('An atlas with<br>its evidence attached.','Use the map to understand the field, and the linked sources to check specific claims. Interpretation, bibliographic records and verified relationships are kept distinguishable.')}<section class="sources-layout section" style="padding-top:10px"><div><h2>What this edition covers</h2><p>${D.stats.chapters} teaching chapters, ${D.stats.landmarks} selected landmark readings, ${D.stats.glossary} glossary concepts, and ${D.stats.concept_edges} explanatory links between fields. These are learning routes, not an exhaustive ontology of robotics or control.</p><p>The application directory records ${A.stats.labs} professor/group entries across ${A.stats.universities} universities. All appointment years are eligible. The university list follows the requested geographic and QS overall cutoff.</p><div class="actions"><a class="text-link" href="#/universities">Inspect the university list</a><a class="text-link" href="downloads/graduate-research-atlas.xlsx">Download workbook</a></div><h2 style="margin-top:40px">Evidence coverage</h2><div class="coverage-bars">${evidence.map(e=>`<div class="coverage-bar"><label><span>${e.title}</span><strong>${e.n}</strong></label><div><i style="width:${e.n/A.stats.labs*100}%"></i></div></div>`).join('')}</div><p class="small">These three categories partition the directory. “Publication attached” does not mean the entire paper was audited. ${A.stats.citation_profiles} records also have dated citation snapshots. Missing values are not zeros.</p></div><div><h2>How to read a connection</h2><ul><li><strong>Conceptual connection:</strong> an editorial explanation of how two methods or questions relate. It is not a claim that one paper caused another.</li><li><strong>Doctoral / postdoctoral connection:</strong> an explicitly sourced training relationship. A thesis examiner is not silently treated as an adviser.</li><li><strong>Named lab connection:</strong> membership in a research group whose PI is documented; weaker than an explicit personal mentorship statement.</li><li><strong>Topic match:</strong> a navigational association using recorded research terms. It is not evidence that two scholars collaborate.</li><li><strong>Paper association:</strong> a selected work appears in a recorded profile. Check the author list and contribution before drawing further conclusions.</li></ul><h2 style="margin-top:35px">What is still unresolved</h2><ul>${G.limits.map(v=>`<li>${esc(v)}</li>`).join('')}</ul></div></section><section class="section"><div class="section-heading"><h2>Judge the claim, not only the venue.</h2><p>Conference papers are central in robotics and machine learning. In control, archival journals often carry the main theoretical contribution. A venue label helps locate a community; it does not replace reading.</p></div><div class="table-scroll"><table><thead><tr><th>Research community</th><th>Representative outlets</th><th>What to examine</th></tr></thead><tbody>${G.venues.map(v=>`<tr><td>${esc(v.family)}</td><td style="min-width:230px">${esc(v.names)}</td><td style="min-width:320px">${esc(v.assessment)}<p>${ext(v.source,'Source / example')}</p></td></tr>`).join('')}</tbody></table></div><div class="chapter-grid">${G.quality_rubric.map(r=>`<article class="chapter-entry"><h3>${esc(r.dimension)}</h3><p>${esc(r.check)}</p></article>`).join('')}</div></section><section class="section"><h2>Affiliation corrections and audit trail</h2><p class="muted" style="margin-top:18px">Moves, leave, incoming appointments and historical records can change the meaning of an application list.</p>${A.findings.map(f=>`<details style="padding:18px 0;border-bottom:1px solid var(--line)"><summary>${esc(f.claim)}</summary><div class="small" style="margin-top:14px">${arr(f.sources).map(s=>typeof s==='string'?ext(s,'Source'):ext(s.url,s.label||'Source')).join(' · ')}</div></details>`).join('')}<details style="margin-top:26px"><summary>Institutions excluded by the requested ranking scope</summary><div class="table-scroll"><table><tbody>${A.exclusions.map(u=>`<tr><td>${esc(u.university)}</td><td>${esc(u.reason||u.scope_decision||u.scope_status)}<p>${ext(u.qs_source||u.source,'Ranking / scope evidence')}</p></td></tr>`).join('')}</tbody></table></div></details></section><section class="sources-layout section"><div><h2>Design references</h2><p>The site follows the open spacing, Pretendard typography, restrained controls and evidence-led presentation of the two requested references, with a pastel-blue palette.</p><ul><li>${ext('https://github.com/postech-psi/test-results','POSTECH PSI test-results repository')}</li><li>${ext('https://github.com/postech-psi/postech-psi.github.io','POSTECH PSI website repository')}</li></ul><p class="small">This atlas is an independent resource. It does not claim PSI or university endorsement. Pretendard is distributed under the <a href="assets/OFL.txt">SIL Open Font License</a>.</p></div><div><h2>Your reading desk</h2><p>Notes, saved papers, saved chapters and shortlisted scholars live in this browser. They are not transmitted to a server. Export a backup before moving devices or clearing browser storage.</p><div class="actions"><a class="button secondary" href="#/saved">Open my reading desk</a><a class="text-link" href="downloads/research-data.json">Download structured research data</a></div></div></section></div>`}
function deskPage(){const entries=Object.keys(state.saved).filter(k=>state.saved[k]),groups={scholar:[],paper:[],chapter:[],path:[]};for(const key of entries){const at=key.indexOf(':'),kind=key.slice(0,at),id=key.slice(at+1);if(groups[kind])groups[kind].push(id)}const has=entries.length;let content='';if(deskTab==='all'||deskTab==='chapter')content+=groups.chapter.length?`<section class="section"><h2>Saved chapters</h2><div class="chapter-grid">${groups.chapter.map(id=>chapterBy[id]).filter(Boolean).map(c=>`<article class="chapter-entry"><h3><a href="${url('chapter',c.id)}">${esc(c.title)}</a></h3><p>${esc(c.question)}</p>${saveButton('chapter',c.id)}${state.notes['chapter:'+c.id]?`<p class="small">Your note: ${esc(state.notes['chapter:'+c.id])}</p>`:''}</article>`).join('')}</div></section>`:'';if(deskTab==='all'||deskTab==='path')content+=groups.path.length?`<section class="section"><h2>Saved reading paths</h2><div class="route-grid" style="margin-top:25px">${groups.path.map(id=>D.paths.find(p=>p.id===id)).filter(Boolean).map(pathPreview).join('')}</div></section>`:'';if(deskTab==='all'||deskTab==='paper')content+=groups.paper.length?`<section class="section"><h2>Saved papers</h2>${groups.paper.map(id=>paperBy[id]).filter(Boolean).map(q=>paperRow(q)).join('')}</section>`:'';if(deskTab==='all'||deskTab==='scholar')content+=groups.scholar.length?`<section class="section"><h2>Shortlisted scholars</h2><div class="result-list" style="margin-top:25px">${groups.scholar.map(id=>scholarBy[id]).filter(Boolean).map(scholarRow).join('')}</div></section>`:'';const noteOnly=Object.entries(state.notes).filter(([key,value])=>value.trim()&&!state.saved[key]);if(noteOnly.length&&(deskTab==='all'))content+=`<section class="section"><h2>Notes on unsaved pages</h2><ul>${noteOnly.map(([key,note])=>{const at=key.indexOf(':'),kind=key.slice(0,at),id=key.slice(at+1),item=kind==='chapter'?chapterBy[id]:kind==='paper'?paperBy[id]:kind==='scholar'?scholarBy[id]:D.paths.find(p=>p.id===id);return item?`<li style="margin:20px 0"><a href="${url(kind,id)}">${esc(item.title||item.professor)}</a><p class="small">${esc(note)}</p></li>`:''}).join('')}</ul></section>`;return `<div class="wrap">${head('Your reading desk.','Keep the papers, questions and research groups you want to revisit. Your notes stay in this browser.',`<div class="actions"><button class="button secondary" id="exportDesk">Export backup</button><button id="importDesk">Import backup</button><input type="file" id="deskFile" accept="application/json" hidden></div>`)}<div class="desk-tabs">${[['all','Everything'],['chapter','Chapters'],['paper','Papers'],['scholar','Scholars'],['path','Paths']].map(([k,t])=>`<button data-desk="${k}" aria-pressed="${deskTab===k}">${t}${k==='all'?' · '+has:' · '+groups[k].length}</button>`).join('')}</div>${content||empty('Your desk is ready','Save a chapter, paper, reading path or scholar profile to collect it here. You can also write notes inside each page.')}<p class="notice">HTML notes and the downloaded Excel checklist are separate. Backups preserve the browser reading desk; they do not synchronize automatically.</p><div class="section"></div></div>`}
const globalIndex=[...D.chapters.map(c=>({kind:'chapter',id:c.id,title:c.title,detail:'Field chapter · '+c.question,text:normal(c.title+' '+c.summary+' '+c.sections.map(s=>s.text).join(' '))})),...D.papers.map(q=>({kind:'paper',id:q.id,title:q.title,detail:q.year+' · '+q.venue,text:paperSearch.get(q.id)})),...A.labs.map(x=>({kind:'scholar',id:x.id,title:x.professor,detail:x.university+' · '+x.lab,text:scholarSearch.get(x.id)})),...A.universities.map(u=>({kind:'university',id:u.university,title:u.university,detail:u.country+' · '+u.lab_count+' recorded groups',text:normal(u.university+' '+u.country)})),...D.glossary.map(t=>({kind:'term',id:t.term,title:t.term,detail:'Glossary · '+t.definition,text:normal(t.term+' '+t.definition)}))];
function searchEverything(){const raw=$('globalSearch').value.trim(),q=normal(raw),tokens=q.split(/\s+/).filter(Boolean);let hits=q?globalIndex.filter(r=>tokens.every(t=>r.text.includes(t))):globalIndex.filter(r=>r.kind==='chapter').slice(0,7);if(q)hits.sort((a,b)=>(normal(b.title).includes(q)?1:0)-(normal(a.title).includes(q)?1:0));$('searchResults').innerHTML=hits.length?`<p class="small">${q?hits.length+' matches':'Start with a field'}</p>`+hits.slice(0,35).map(r=>`<a class="search-result" href="${r.kind==='university'?url('scholars')+'?university='+encodeURIComponent(r.id):r.kind==='term'?url('glossary')+'?q='+encodeURIComponent(r.id):url(r.kind,r.id)}"><strong>${esc(r.title)}</strong><span>${esc(r.detail.slice(0,180))}</span></a>`).join(''):empty('No results','Try a shorter name, acronym or method.');}
function openSearch(){if(!$('searchDialog').open)$('searchDialog').showModal();searchEverything();$('globalSearch').focus()}
function parseRoute(){let h=location.hash.replace(/^#\/?/,'');const[part,qs='']=h.split('?');const pieces=part.split('/');return {type:pieces[0]||'home',id:decodeURIComponent(pieces.slice(1).join('/')),params:new URLSearchParams(qs)}}
function renderRoute(scroll=true){let r;try{r=parseRoute()}catch{r={type:'missing',id:'',params:new URLSearchParams()}}currentRoute=r;if(r.type==='scholars'){if(r.params.has('chapter')||r.params.has('university'))filters.scholars={q:'',region:'',university:'',chapter:'',evidence:''};for(const k of ['chapter','university'])if(r.params.has(k)){filters.scholars[k]=r.params.get(k);pages.scholars=1}}if(r.type==='glossary'&&r.params.has('q'))filters.glossary.q=r.params.get('q');if(r.type==='network'&&personBy[r.id])networkFocus=r.id;const view={home:overview,chapters:chaptersPage,chapter:()=>chapterPage(r.id),scholars:scholarsPage,scholar:()=>scholarPage(r.id),papers:papersPage,paper:()=>paperPage(r.id),universities:universitiesPage,glossary:glossaryPage,learn:learnPage,path:()=>pathPage(r.id),network:networkPage,about:aboutPage,saved:deskPage}[r.type]||notFound;$('main').innerHTML=view();let nav=r.type==='chapter'?'chapters':r.type==='scholar'?'scholars':r.type==='paper'?'papers':r.type==='path'?'learn':r.type;document.querySelectorAll('[data-nav]').forEach(el=>{if(el.dataset.nav===nav)el.setAttribute('aria-current','page');else el.removeAttribute('aria-current')});$('navigation').classList.remove('open');$('menu').setAttribute('aria-expanded','false');const titles={chapter:chapterBy[r.id]?.title,scholar:scholarBy[r.id]?.professor,paper:paperBy[r.id]?.title,path:D.paths.find(p=>p.id===r.id)?.title};document.title=(titles[r.type]||({home:'Control, Autonomy & Robot Learning',chapters:'Field Encyclopedia',scholars:'Scholars & Labs',papers:'Paper Library',universities:'Universities',glossary:'Glossary',learn:'Reading Paths',network:'Scholar Connections',about:'Sources & Coverage',saved:'My Reading Desk'}[r.type]||'Page'))+' — Research Atlas';if(scroll)window.scrollTo(0,0)}
function refreshResults(type){const ids={scholars:'scholarResults',papers:'paperResults',universities:'universityResults',glossary:'glossaryResults'},fn={scholars:scholarResults,papers:paperResults,universities:universityResults,glossary:glossaryResults};if($(ids[type]))$(ids[type]).innerHTML=fn[type]()}
function download(name,obj){const blob=new Blob([JSON.stringify(obj,null,2)],{type:'application/json'}),link=document.createElement('a'),u=URL.createObjectURL(blob);link.href=u;link.download=name;link.click();setTimeout(()=>URL.revokeObjectURL(u),1000)}
function normalizeBackup(d){const out={saved:{},notes:{},reviewed:{}};if(d.version===1&&d.state){const s=d.state;for(const [k,v] of Object.entries(s.saved||{}))if(v&&/^(chapter|paper|scholar|path):[\w-]+$/.test(k))out.saved[k]=true;for(const [k,v]of Object.entries(s.notes||{}))if(typeof v==='string'&&/^(chapter|paper|scholar|path):[\w-]+$/.test(k))out.notes[k]=v.slice(0,50000);for(const[k,v]of Object.entries(s.reviewed||{}))if(scholarBy[k]&&v)out.reviewed[k]=true;return out}if(d.progress){for(const[id,v]of Object.entries(d.progress)){if(!scholarBy[id])continue;if(v.shortlisted)out.saved['scholar:'+id]=true;if(typeof v.notes==='string')out.notes['scholar:'+id]=v.notes.slice(0,50000);if(v.reviewed)out.reviewed[id]=true}return out}throw Error('Not a reading-desk backup')}
document.addEventListener('click',e=>{const el=e.target.closest('a,button,[data-map],[data-person]');if(!el)return;
 if(el.dataset.scroll){e.preventDefault();$(el.dataset.scroll)?.scrollIntoView({behavior:'auto',block:'start'});return}
 if(el.dataset.saveKind){const {saveKind:kind,saveId:id}=el.dataset,key=saveKey(kind,id);if(state.saved[key])delete state.saved[key];else state.saved[key]=true;persist();if(currentRoute.type==='saved')renderRoute(false);else document.querySelectorAll('[data-save-kind]').forEach(b=>{if(b.dataset.saveKind===kind&&b.dataset.saveId===id){b.classList.toggle('saved',!!state.saved[key]);b.setAttribute('aria-pressed',String(!!state.saved[key]));b.textContent=state.saved[key]?'Saved':kind==='scholar'?'Shortlist':'Save to reading desk'}});toast(state.saved[key]?'Saved to your reading desk':'Removed from saved items');return}
 if(el.dataset.map){mapFocus=el.dataset.map;$('mapMount').innerHTML=fieldMap();document.querySelector('[data-map="'+mapFocus+'"]')?.focus({preventScroll:true});return}
 if(el.dataset.zoom!==undefined){const z=Number(el.dataset.zoom);mapZoom=z===0?1:Math.max(.8,Math.min(1.8,mapZoom+z*.2));$('mapMount').innerHTML=fieldMap();return}
 if(el.dataset.person){networkFocus=el.dataset.person;$('networkPerson').value=networkFocus;$('networkMount').innerHTML=networkDiagram();return}
 if(el.dataset.page){pages[el.dataset.page]+=Number(el.dataset.change);refreshResults(el.dataset.page);document.querySelector('.filters')?.scrollIntoView({block:'start'});return}
 if(el.dataset.clear){const type=el.dataset.clear;for(const k of Object.keys(filters[type]))filters[type][k]='';if(type==='papers')filters.papers.sort='year-desc';if(pages[type])pages[type]=1;history.replaceState(null,'',url(type));renderRoute(false);return}
 if(el.dataset.desk){deskTab=el.dataset.desk;renderRoute(false);return}
 if(el.id==='exportDesk'){download('research-atlas-reading-desk.json',{version:1,exported:new Date().toISOString(),state});return}
 if(el.id==='importDesk'){$('deskFile').click();return}
 if(el.closest('#searchResults')&&el.tagName==='A')$('searchDialog').close();
});
document.addEventListener('keydown',e=>{if((e.key==='Enter'||e.key===' ')&&(e.target.hasAttribute('data-map')||e.target.hasAttribute('data-person'))){e.preventDefault();e.target.dispatchEvent(new MouseEvent('click',{bubbles:true}))}if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='k'){e.preventDefault();openSearch()}if(e.key==='/'&&!/INPUT|TEXTAREA|SELECT/.test(e.target.tagName)){e.preventDefault();openSearch()}});
document.addEventListener('input',e=>{const el=e.target;if(el.dataset.note){state.notes[el.dataset.note]=el.value;persist()}if(el.dataset.filter&&el.tagName==='INPUT'){const type=el.closest('[data-filter-group]').dataset.filterGroup;filters[type][el.dataset.filter]=el.value;if(pages[type])pages[type]=1;refreshResults(type)}});
document.addEventListener('change',async e=>{const el=e.target;if(el.dataset.filter&&el.tagName==='SELECT'){const type=el.closest('[data-filter-group]').dataset.filterGroup;filters[type][el.dataset.filter]=el.value;if(pages[type])pages[type]=1;refreshResults(type)}if(el.dataset.reviewed){state.reviewed[el.dataset.reviewed]=el.checked;persist()}if(el.id==='networkPerson'){networkFocus=el.value;$('networkMount').innerHTML=networkDiagram()}if(el.id==='networkDepth'){networkDepth=Number(el.value);$('networkMount').innerHTML=networkDiagram()}if(el.id==='networkKind'){networkKind=el.value;$('networkMount').innerHTML=networkDiagram()}if(el.id==='deskFile'){try{const file=el.files[0];if(!file||file.size>5e6)throw Error('Invalid file');const incoming=normalizeBackup(JSON.parse(await file.text()));state={saved:{...state.saved,...incoming.saved},notes:{...state.notes,...incoming.notes},reviewed:{...state.reviewed,...incoming.reviewed}};persist();renderRoute(false);toast('Reading desk imported')}catch{toast('Could not read that backup. Existing notes were preserved.')}}});
$('searchOpen').onclick=openSearch;$('closeSearch').onclick=()=>$('searchDialog').close();$('globalSearch').oninput=searchEverything;$('menu').onclick=()=>{const yes=$('navigation').classList.toggle('open');$('menu').setAttribute('aria-expanded',String(yes))};$('searchDialog').addEventListener('click',e=>{if(e.target===$('searchDialog')){const r=$('searchDialog').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)$('searchDialog').close()}});window.addEventListener('hashchange',()=>renderRoute(true));renderRoute();
